#include "air_formation_internal.h"
/* $080B1A..$081838. Death routing is by authored flight phase, not weapon ID. */
static struct NativeEntity*fx(struct WeaponWorld*w,struct NativeEntity*e,enum BossFxKind kind){struct EnemyActor*q=&e->payload.enemy;struct NativeEntity*n=boss_fx_spawn(w,entity_ref(e),ENTITY_FIRST_CHILD,&q->actor.transform,kind);if(n){n->payload.enemy.scale_x=q->scale_x;n->payload.enemy.scale_y=q->scale_y;}return n;}
static struct NativeEntity*shard(struct WeaponWorld*w,struct NativeEntity*e,unsigned kind,int forward,int flip){struct EnemyActor*q=&e->payload.enemy;struct NativeEntity*n=af_child(w,e,forward?AF_SHARD_FORWARD:AF_SHARD,ENTITY_FIRST_CHILD);if(!n)return 0;n->payload.enemy.formation.variant=kind;n->payload.enemy.scale_x=q->scale_x;n->payload.enemy.scale_y=q->scale_y;if(forward){n->payload.enemy.selector=(q->selector&0xff00)|255;n->payload.enemy.formation.speed=q->formation.speed;}if(flip)n->payload.enemy.actor.transform.facing^=1;return n;}
int af_pattern(struct WeaponWorld*w,struct NativeEntity*e,unsigned i){if(i>1)return enemy_fault(w);struct NativeEntity*n=af_child(w,e,AF_PATTERN,ENTITY_LAST_CHILD);if(!n)return 0;struct EnemyActor*q=&n->payload.enemy,*p=&e->payload.enemy;q->formation.variant=i;q->scale_x=p->scale_x;q->scale_y=p->scale_y;if(i){q->selector=(p->selector&0xff00)|255;q->formation.speed=p->formation.speed;}return 1;}
static void boost(struct WeaponWorld*w,struct WeaponActor*a){if((int8_t)tk_random(w)<=0){a->vx=tk_word(a->vx*((tk_random(w)&3)+2))>>1;a->vy=tk_word(a->vy*((tk_random(w)&3)+2))>>1;}}
static void shard_velocity(struct WeaponWorld*w,struct EnemyActor*q,int forward){struct WeaponActor*a=&q->actor;if(q->formation.speed<=0)q->formation.speed=1024;if(forward){unsigned angle=((tk_random(w)&31)-16+(q->selector>>8))&255;int16_t speed=tk_word(q->formation.speed*2);a->vx=tk_word((int32_t)boss_trig[1][angle]*speed>>8);a->vy=tk_word((int32_t)boss_trig[0][angle]*speed>>8);}else{uint16_t r=tk_random(w);unsigned angle=(r&30)+48;int16_t vy=tk_word(boss_trig[0][angle]*((r&7)+1))>>2;a->vy=tk_word((int32_t)vy*q->formation.speed>>8);a->vx=tk_word((int32_t)boss_trig[1][angle]*q->formation.speed>>8);}boost(w,a);q->formation.launch_speed=a->vy>3072?3072:a->vy;a->ay=-32;}
int af_death_enter(struct WeaponWorld*w,struct NativeEntity*e){struct EnemyActor*q=&e->payload.enemy;struct WeaponActor*a=&q->actor;struct EnemyActor*p;struct NativeEntity*n;unsigned angle=q->selector>>8;int forward=0;
 switch(a->state){
 case AF_HOP:a->vy=-512;a->ay=-80;a->vx=(a->transform.facing&1?q->formation.speed:tk_word(-q->formation.speed))>>1;q->formation.timer=(tk_random(w)&63)+60;af_start(q,AFA_HOP);a->state=AF_HOP_WAIT;break;
 case AF_TUMBLE:af_path_begin(q,12+(a->transform.facing&1));a->phase=0;a->state=AF_TUMBLE_RUN;break;
 case AF_TUMBLE_ALT:af_path_begin(q,16+2*(a->transform.facing&1)+((int8_t)angle>=24&&(int8_t)angle<=104));a->phase=0;a->state=AF_TUMBLE_RUN;break;
 case AF_SKID:af_path_begin(q,14+(a->transform.facing&1));a->phase=0;q->formation.base_speed=tk_word(q->formation.base_speed*2);a->state=AF_SKID_RUN;break;
 case AF_SHRINK:af_path_begin(q,20+(a->transform.facing&1));a->phase=0;interaction_priority(w,a,0x2000,20);q->formation.timer=1;a->state=AF_SHRINK_RUN;break;
 case AF_ARC:af_start(q,a->transform.facing&1?AFA_ARC_RIGHT:AFA_ARC_LEFT);a->phase=0;q->dead=1;q->formation.selector=angle>=248?0:angle>>4;{int16_t speed=tk_word(q->formation.speed+(q->formation.speed>>1));a->vx=tk_word((int32_t)boss_trig[1][angle]*speed>>8);a->vy=tk_word((int32_t)boss_trig[0][angle]*speed>>8);}break;
 case AF_WATER_CRASH:p=tk_parent(w,e);if(!p)return 0;if((int8_t)p->params[7]>=2&&!af_surface(w,e,1))return 0;/* FALLTHROUGH */
 case AF_CRASH:if(!fx(w,e,BFX_SMOKE)||!af_pattern(w,e,0))return 0;if(!shard(w,e,0,0,0)||!shard(w,e,0,0,1)||!shard(w,e,1,0,0)||!shard(w,e,2,0,0))return 0;af_schedule(e,AF_SOUND_REMOVE);return 2;
 case AF_SPLIT:p=tk_parent(w,e);if(!p)return 0;if(!(p->params[7]&1)){int admitted=boss_sprite_admitted(w);if(w->fault)return 0;if(admitted)for(unsigned i=0;i<4;i++){n=boss_radial_blast(w,e,i);if(!n)return 0;n->payload.enemy.scale_x=q->scale_x;n->payload.enemy.scale_y=q->scale_y;}}
  if(!w->sound||!w->sound(w->scene,0x10ba,1))return enemy_fault(w);if(!fx(w,e,BFX_SMOKE)||!af_pattern(w,e,1))return 0;if(!shard(w,e,0,1,0)||!shard(w,e,0,1,1)||!shard(w,e,1,1,0)||!shard(w,e,2,1,0))return 0;af_schedule(e,AF_SOUND_REMOVE);return 2;
 case AF_SHARD_FORWARD:forward=1;/* FALLTHROUGH */
 case AF_SHARD:if(q->formation.variant>=3)return enemy_fault(w);af_start(q,AFA_SHARD_A+q->formation.variant);if(forward&&q->formation.variant==1)a->transform.facing=angle>64&&angle<=192?0:1;interaction_priority(w,a,0xc000,28);a->palette=0x48;shard_velocity(w,q,forward);a->state=AF_SHARD_RUN;break;
 case AF_DEBRIS:{static const uint8_t anim[]={AFA_DEBRIS_B,AFA_DEBRIS_A,AFA_DEBRIS_C,AFA_DEBRIS_D,AFA_DEBRIS_E};if(q->formation.variant>=5)return enemy_fault(w);af_start(q,anim[q->formation.variant]);a->palette=q->formation.variant>=3?11:10;p=tk_parent(w,e);if(!p)return 0;q->formation.speed=p->formation.speed;q->selector=p->selector;interaction_priority(w,a,0xc000,28);shard_velocity(w,q,1);a->state=AF_SHARD_RUN;break;}
 case AF_GLINT:a->palette=4;af_start(q,AFA_GLINT);break;
 case AF_PATTERN:if(q->formation.variant>1)return enemy_fault(w);q->formation.delay=air_formation_patterns[q->formation.variant].period;q->formation.timer=air_formation_patterns[q->formation.variant].life;break;
 case AF_SOUND_REMOVE:if(!tk_sound(w,0x1023))return 0;/* FALLTHROUGH */
 case AF_REMOVE:a->phase=255;entity_delete(w->entities,e);return 0;
 default:return enemy_fault(w);
 }return !w->fault;
}
static int pattern_frame(struct WeaponWorld*w,struct NativeEntity*e){struct EnemyActor*q=&e->payload.enemy,*p=tk_parent(w,e);if(!p)return 0;const struct BossPatternData*t=&air_formation_patterns[q->formation.variant];struct WeaponActor*a=&q->actor;q->scale_x=p->scale_x;q->scale_y=p->scale_y;if(!--q->formation.delay){q->formation.delay=t->period;if(t->follow){int16_t dx=p->actor.transform.facing&1?tk_word(-t->dx):t->dx,dy=p->actor.transform.facing&1?tk_word(-t->dy):t->dy;m4_screen(w,a,tk_word(tk_sx(w,&p->actor)+dx),tk_word(tk_sy(w,&p->actor)+dy));}if(!w->rng)return enemy_fault(w);unsigned v=air_formation_pattern_choices[q->formation.variant][source_random(w->rng,16)];struct NativeEntity*n;if(!q->formation.variant){static const uint8_t kinds[]={BFX_DEBRIS8,BFX_DEBRIS9,BFX_DEBRIS10,BFX_DEBRIS6,BFX_DEBRIS7};n=boss_fx_spawn(w,entity_ref(e),ENTITY_LAST_CHILD,&a->transform,kinds[v]);}else{n=af_child(w,e,AF_DEBRIS,ENTITY_LAST_CHILD);if(n)n->payload.enemy.formation.variant=v;}if(!n)return 0;int16_t dx=source_random(w->rng,t->spread_x),dy=source_random(w->rng,t->spread_y);if(a->transform.facing&1)dx=tk_word(-dx);if(a->transform.facing&2)dy=tk_word(-dy);transform_integer_offset(&n->payload.enemy.actor.transform,dx,dy);n->payload.enemy.actor.display_flags|=a->display_flags&64;n->payload.enemy.scale_x=q->scale_x;n->payload.enemy.scale_y=q->scale_y;}if(!--q->formation.timer)entity_delete(w->entities,e);return !w->fault;}
static int terrain_hit(struct WeaponWorld*w,struct WeaponActor*a){if(!w->interactions||!w->interactions->terrain)return enemy_fault(w),-1;uint8_t shape;int r=terrain_weapon_point_shape(w->interactions->terrain,a,(int16_t)(a->transform.x>>8),transform_y_up(&a->transform),&shape);if(!r)return enemy_fault(w),-1;return shape&&!(shape&240);}
static void bounds(struct WeaponWorld*w,struct NativeEntity*e){if(af_outside(w,&e->payload.enemy.actor,0))af_schedule(e,AF_SOUND_REMOVE);}
int af_death_frame(struct WeaponWorld*w,struct NativeEntity*e,unsigned s){struct EnemyActor*q=&e->payload.enemy;struct WeaponActor*a=&q->actor;int r;
 if(s==AF_PATTERN)return pattern_frame(w,e);
 if(s==AF_GLINT){if(interaction_move(w,a,WMOVE_SYNC)<0)return 0;if(af_animate(w,e))af_schedule(e,AF_DELETE);return !w->fault;}
 if(s==AF_SHARD_RUN){r=interaction_move(w,a,WMOVE_FALL);if(r<0)return 0;if(r){a->ay=-32;a->vx>>=2;q->formation.launch_speed>>=1;a->vy=q->formation.launch_speed;af_schedule(e,AF_DELETE);}af_animate(w,e);if(interaction_outside(w,a,air_formation_bounds[1],1))af_schedule(e,AF_DELETE);return !w->fault;}
 if(s==AF_HOP_WAIT||s==AF_HOP_FALL){if(s==AF_HOP_WAIT){q->formation.timer=tk_word(q->formation.timer-1);if(!q->formation.timer){a->state=AF_HOP_FALL;if((tk_random(w)&15)<=5)af_schedule(e,AF_SPLIT);}}r=interaction_move(w,a,WMOVE_FALL);if(r<0)return 0;if(r)af_schedule(e,AF_CRASH);af_animate(w,e);if(af_front_edge(w,a))af_schedule(e,AF_SPLIT);if(af_water(w,a))af_schedule(e,AF_WATER_CRASH);bounds(w,e);return !w->fault;}
 if(s==AF_ARC){r=interaction_move(w,a,WMOVE_POINT);if(r<0)return 0;if(r)af_schedule(e,AF_CRASH);af_animate(w,e);if(af_water(w,a))af_schedule(e,AF_WATER_CRASH);if(af_front_edge(w,a))af_schedule(e,AF_SPLIT);bounds(w,e);return !w->fault;}
 if(s==AF_TUMBLE_RUN||s==AF_SKID_RUN||s==AF_SKID_FALL||s==AF_SHRINK_RUN){
  if(s==AF_SKID_RUN){int16_t base=tk_word(q->formation.base_speed-a->ay);if(base<0){base=0;a->ay=-32;af_schedule(e,AF_SKID_FALL);q->entry=0;}q->formation.base_speed=base;}
  if(s==AF_SKID_FALL){r=interaction_move(w,a,WMOVE_FALL);if(r<0)return 0;if(r)af_schedule(e,AF_CRASH);}else af_speed(q);
  if(s==AF_SHRINK_RUN&&q->scale_x>16){q->formation.timer=tk_word(q->formation.timer-1);if(!q->formation.timer){q->formation.timer=1;q->scale_x--;q->scale_y--;}}
  if(af_path(w,e)>0)af_schedule(e,s==AF_SHRINK_RUN?AF_CRASH:AF_SOUND_REMOVE);af_animate(w,e);
  if(s!=AF_SHRINK_RUN){r=terrain_hit(w,a);if(r<0)return 0;if(r)af_schedule(e,AF_CRASH);if(s==AF_TUMBLE_RUN&&af_front_edge(w,a))af_schedule(e,AF_SPLIT);if(af_water(w,a))af_schedule(e,AF_WATER_CRASH);}bounds(w,e);return !w->fault;
 }return enemy_fault(w);
}

/* $0817FA/$08186C/$081884/$08189C/$0818AA: original helper aliases.
 * No incoming converted graph currently calls these entries. */
int air_formation_aux(struct WeaponWorld*w,struct NativeEntity*e,enum AirFormationAux kind){if(e->kind!=ENTITY_ENEMY)return enemy_fault(w);struct EnemyActor*q=&e->payload.enemy;switch(kind){case AF_AUX_POSE_C:af_start(q,AFA_PATH_C);return 1;case AF_AUX_ACCEL_SLOW:case AF_AUX_ACCEL_FAST:q->actor.ax=q->formation.speed>>(kind==AF_AUX_ACCEL_SLOW?7:4);if(!(q->actor.transform.facing&1))q->actor.ax=tk_word(-q->actor.ax);return 1;case AF_AUX_DEBRIS:return af_pattern(w,e,0);case AF_AUX_RADIAL:for(unsigned i=0;i<4;i++)if(!boss_radial_blast(w,e,i))return 0;return 1;default:return enemy_fault(w);}}
